package sfz.stream.l06.demo

import org.apache.kafka.common.serialization.Serdes
import org.apache.kafka.common.serialization.StringDeserializer
import org.apache.kafka.common.serialization.StringSerializer
import org.apache.kafka.streams.StreamsBuilder
import org.apache.kafka.streams.Topology
import org.apache.kafka.streams.kstream.Consumed
import org.apache.kafka.streams.kstream.Joined
import org.apache.kafka.streams.kstream.Materialized
import org.apache.kafka.streams.kstream.Produced
import org.apache.kafka.streams.kstream.ValueJoiner
import org.apache.kafka.streams.state.Stores
import java.time.Duration

/**
 * Orders joined with the customer's tier, three ways: an ordinary (unversioned) table, a versioned table, and a
 * versioned table with a 5-minute grace period on the order side. Customer c-1 is silver from 09:00 and gold from
 * 10:00. Each scenario pipes the same records in a different arrival order, and ends with order o-9 at 10:30.
 */
fun main() {
    val variants = listOf("unversioned" to topology(versioned = false, grace = null),
        "versioned" to topology(versioned = true, grace = null),
        "versioned+grace" to topology(versioned = true, grace = Duration.ofMinutes(5)))
    val scenarios = listOf(
        "A1 o-1 (09:30) arrives before the upgrade" to listOf("tier silver 09:00", "order o-1 09:30", "tier gold 10:00", "order o-9 10:30"),
        "A2 o-1 (09:30) arrives after the upgrade" to listOf("tier silver 09:00", "tier gold 10:00", "order o-1 09:30", "order o-9 10:30"),
        "B  upgrade (10:00) arrives after o-2 (10:02)" to listOf("tier silver 09:00", "order o-2 10:02", "tier gold 10:00", "order o-9 10:30"),
    )
    println("%-45s %-21s %-21s %s".format("scenario", "unversioned", "versioned", "versioned+grace"))
    for ((name, records) in scenarios) {
        val results = variants.map { (label, t) -> run(t, label, records) }
        println("%-45s %-21s %-21s %s".format(name, *results.toTypedArray()))
    }
}

private fun topology(versioned: Boolean, grace: Duration?): Topology {
    val builder = StreamsBuilder()
    val consumed = Consumed.with(Serdes.String(), Serdes.String())
    val tiers = if (versioned) {
        // every version of each customer's tier, with the time it took effect, kept for 7 days
        builder.table("customer-tiers", consumed, Materialized.`as`<String, String>(
            Stores.persistentVersionedKeyValueStore("tiers", Duration.ofDays(7))))
    } else {
        builder.table("customer-tiers", consumed)          // the latest tier per customer, nothing else
    }
    var joined = Joined.with(Serdes.String(), Serdes.String(), Serdes.String())
    if (grace != null) joined = joined.withGracePeriod(grace)   // hold each order this long (stream time) before joining
    builder.stream("orders", consumed)
        .leftJoin(tiers, ValueJoiner<String, String?, String> { order, tier -> "$order=${tier ?: "none"}" }, joined)
        .to("orders-enriched", Produced.with(Serdes.String(), Serdes.String()))
    return builder.build()
}

/** Pipes "tier <tier> <time>" and "order <id> <time>" records for customer c-1; returns the orders' tiers. */
private fun run(topology: Topology, label: String, records: List<String>): String = drive(topology, "tier-join-$label") { driver ->
    val orders = driver.createInputTopic("orders", StringSerializer(), StringSerializer())
    val tiers = driver.createInputTopic("customer-tiers", StringSerializer(), StringSerializer())
    for (r in records) {
        val (kind, value, time) = r.split(" ")
        if (kind == "tier") tiers.pipeInput("c-1", value, at(time)) else orders.pipeInput("c-1", value, at(time))
    }
    driver.createOutputTopic("orders-enriched", StringDeserializer(), StringDeserializer())
        .readValuesToList().joinToString(" ")
}

package sfz.stream.l06.demo

import org.apache.kafka.common.serialization.Serdes
import org.apache.kafka.common.serialization.StringDeserializer
import org.apache.kafka.common.serialization.StringSerializer
import org.apache.kafka.streams.StreamsBuilder
import org.apache.kafka.streams.kstream.Consumed
import org.apache.kafka.streams.kstream.Produced
import org.apache.kafka.streams.kstream.ValueJoiner
import java.util.function.Function

/**
 * A table-table join kept up to date as either side changes: cards (card id -> account id) joined with account
 * tiers (account id -> tier) on the card's account, a foreign-key join. The result is a table, card -> tier, and the
 * output topic is its changelog.
 */
fun main() {
    val builder = StreamsBuilder()
    val consumed = Consumed.with(Serdes.String(), Serdes.String())
    val tiers = builder.table("account-tiers", consumed)
    builder.table("cards", consumed)
        .join(tiers, Function<String, String> { account -> account },                 // which tiers row: the card's account
            ValueJoiner<String, String, String> { account, tier -> "$account $tier" })
        .toStream()
        .to("card-tiers", Produced.with(Serdes.String(), Serdes.String()))

    drive(builder.build(), "view-join-demo") { driver ->
        val cards = driver.createInputTopic("cards", StringSerializer(), StringSerializer())
        val accountTiers = driver.createInputTopic("account-tiers", StringSerializer(), StringSerializer())
        val view = driver.createOutputTopic("card-tiers", StringDeserializer(), StringDeserializer())
        fun step(what: String, change: () -> Unit) {
            change()
            val out = view.readKeyValuesToList().joinToString { "${it.key} -> ${it.value ?: "(deleted)"}" }
            println("%-34s view changes: %s".format(what, out.ifEmpty { "none" }))
        }
        step("tiers: acct-1 silver, acct-2 gold") { accountTiers.pipeInput("acct-1", "silver"); accountTiers.pipeInput("acct-2", "gold") }
        step("cards: card-1, card-2 on acct-1") { cards.pipeInput("card-1", "acct-1"); cards.pipeInput("card-2", "acct-1") }
        step("card: card-3 on acct-2") { cards.pipeInput("card-3", "acct-2") }
        step("tier: acct-1 becomes gold") { accountTiers.pipeInput("acct-1", "gold") }
        step("card: card-3 moves to acct-1") { cards.pipeInput("card-3", "acct-1") }
        step("card: card-2 is deleted") { cards.pipeInput("card-2", null as String?) }
        step("tier: acct-1 is deleted") { accountTiers.pipeInput("acct-1", null as String?) }
    }
}

package sfz.stream.l06.demo

import org.apache.kafka.common.utils.Utils
import java.util.zip.CRC32

/** The Java producer's partition for a key: murmur2 of the bytes, made positive, modulo the count. */
fun murmur2Partition(key: String, n: Int) = Utils.toPositive(Utils.murmur2(key.toByteArray())) % n

/** librdkafka's default ("consistent_random") for a non-empty key: CRC32 of the bytes, modulo the count. */
fun crc32Partition(key: String, n: Int) = (CRC32().apply { update(key.toByteArray()) }.value % n).toInt()

/**
 * Where 10,000 customer keys land in two topics, and how many land on a different partition number in the second
 * one. A partitioned join of the two topics loses every one of those keys.
 */
fun main() {
    val keys = (0 until 10_000).map { "c-$it" }
    println("c-42: partition ${murmur2Partition("c-42", 3)} of 3 in orders, partition ${murmur2Partition("c-42", 2)} of 2 in customer-tiers")
    fun share(name: String, a: (String) -> Int, b: (String) -> Int) {
        val differ = keys.count { a(it) != b(it) }
        println("%-46s %5d of %d keys on a different partition (%.1f%%)".format(name, differ, keys.size, 100.0 * differ / keys.size))
    }
    share("orders 3, tiers 3, both Java producers", { murmur2Partition(it, 3) }, { murmur2Partition(it, 3) })
    share("orders 3, tiers 2, both Java producers", { murmur2Partition(it, 3) }, { murmur2Partition(it, 2) })
    share("orders 6, tiers grown from 6 to 12", { murmur2Partition(it, 6) }, { murmur2Partition(it, 12) })
    share("orders 3 (Java), tiers 3 (librdkafka default)", { murmur2Partition(it, 3) }, { crc32Partition(it, 3) })
}

package sfz.stream.l06.demo

import java.time.Duration
import java.time.Instant

/** One card authorization result. */
data class Auth(val card: String, val approved: Boolean, val at: Instant)

/**
 * A stored query, compiled to a small state machine per card: three declines in a row, then an approval, all within
 * 2 minutes of the first decline ("card testing": a fraudster tries numbers until one works). The events flow past
 * it; nothing is stored but each card's partial match.
 */
class CardTestingPattern(private val within: Duration = Duration.ofMinutes(2)) {
    /** Per card: the declines seen so far in the current partial match (the state machine's state). */
    private val partial = mutableMapOf<String, MutableList<Instant>>()

    /** Feeds one event; returns a description of the match if this event completes one. */
    fun onEvent(e: Auth): String? {
        val declines = partial.getOrPut(e.card) { mutableListOf() }
        if (declines.isNotEmpty() && Duration.between(declines.first(), e.at) > within) declines.clear() // too old: drop it
        if (!e.approved) {
            declines += e.at
            if (declines.size > 3) declines.removeAt(0)       // keep the three most recent declines
            return null
        }
        val match = if (declines.size == 3) "MATCH ${e.card}: 3 declines from ${hms(declines.first())}, approved at ${hms(e.at)}" else null
        declines.clear()                                      // an approval ends any partial match
        return match
    }

    fun state(card: String): String = "${partial[card]?.size ?: 0} declines"
}

fun main() {
    val t0 = Instant.parse("2026-11-07T10:00:00Z")
    fun ev(card: String, ok: Boolean, sec: Long) = Auth(card, ok, t0.plusSeconds(sec))
    val events = listOf(
        ev("card-1", false, 0), ev("card-2", true, 5), ev("card-1", false, 20), ev("card-1", false, 41),
        ev("card-1", true, 50),                                   // card-1: decline, decline, decline, approve in 50 s
        ev("card-3", false, 60), ev("card-3", false, 70), ev("card-3", true, 80),   // only two declines
        ev("card-4", false, 100), ev("card-4", false, 130), ev("card-4", false, 160), ev("card-4", true, 250),  // too slow
    )
    val pattern = CardTestingPattern()
    for (e in events) {
        val match = pattern.onEvent(e)
        println("%s %-7s %-8s state %-10s %s".format(hms(e.at), e.card,
            if (e.approved) "approved" else "declined", pattern.state(e.card), match ?: ""))
    }
}

